import {defaultInteraction,InteractionSimulator} from './runtime.mjs';
export function mountObjectInteractions(h){
 const $=id=>document.getElementById(id),panel=document.createElement('section');panel.dataset.panel='interactions';panel.id='objectInteractionsPanel';
 panel.innerHTML=`<h2>Tương tác & linh thạch</h2><p class="hint">Cấu hình riêng cho từng vật thể đã đặt trong map, không áp cho tất cả bản sao của ảnh. Xuất cả map bundle để đưa sang game, không xuất từng vật thể.</p><label>Vật thể trong map<select id="interactionObjectList"></select></label><p id="interactionSummary" class="hint"></p><div id="interactionFields" hidden>
<label>ID vật thể trong map<input id="interactiveObjectId" maxlength="100" spellcheck="false"></label><label><input id="interactionEnabled" type="checkbox"> Cho phép tương tác</label><div id="interactionSettings">
<label>Loại<select id="interactionType"><option value="mine">Đào linh thạch / khoáng sản</option><option value="gather">Thu thập tài nguyên</option><option value="custom">Tương tác tùy chỉnh</option></select></label><label>Mã hành động (actionId)<input id="interactionActionId" maxlength="100" spellcheck="false"></label><label>Chữ trên nút<input id="interactionLabel" maxlength="100"></label>
<div class="pair"><label>Khoảng cách tương tác<input id="interactionRange" type="number" min="1" max="2000" step="1"></label><label>Thời gian thao tác (giây)<input id="interactionDuration" type="number" min="0.1" max="600" step="0.1"></label></div>
<div class="pair"><label>Điểm thao tác lệch X<input id="interactionPointX" type="number" min="-4096" max="4096"></label><label>Điểm thao tác lệch Y<input id="interactionPointY" type="number" min="-4096" max="4096"></label></div><p class="hint">Điểm lệch tính theo ảnh trước khi quay/lật/phóng; 0,0 là neo gốc vật thể, không phải tâm tán cây. Khoảng cách tính bằng đơn vị thế giới từ chân người chơi.</p>
<div id="interactionRewardFields"><label>Mã tài nguyên<input id="interactionResourceId" maxlength="100" spellcheck="false"></label><div class="pair"><label>Nhận ít nhất<input id="interactionRewardMin" type="number" min="1" max="1000000" step="1"></label><label>Nhận nhiều nhất<input id="interactionRewardMax" type="number" min="1" max="1000000" step="1"></label></div><p class="hint">spirit_stone = Linh thạch. Các số mặc định chỉ là gợi ý để test, có thể chỉnh cân bằng game.</p></div>
<label><input id="interactionDeplete" type="checkbox"> Vật thể biến mất sau khi hoàn tất</label><label>Thời gian có lại / hồi thao tác (giây)<input id="interactionRespawn" type="number" min="0" max="86400" step="1"></label><p class="hint">0 = không tái xuất hiện nếu đã biến mất. Tắt Biến mất sẽ giữ hình nhưng chờ hết thời gian hồi mới tương tác tiếp. Tùy chỉnh dùng handler game, không tự phát tiền.</p></div></div>
<label><input id="interactionMarkers" type="checkbox"> Hiện điểm & vùng tương tác</label><button id="jumpInteractiveObject">◎ Chọn / kéo vật thể trên map</button><p class="hint">Bật Chạy thử, đến gần rồi bấm nút ⛏ trên preview để thử đào, rung nhẹ, biến mất và hồi lại. Di chuyển sẽ hủy thao tác. Số nhận chỉ là mô phỏng; không ghi tiền vào game.</p><button id="downloadInteractionPrompt">Tải prompt tích hợp vào game (.md)</button><a href="INTERACTIONS-CODEX.md" target="_blank" rel="noopener">Đọc cấu trúc / hướng dẫn ↗</a>`;
 document.querySelector('aside.right').append(panel);const menu=document.createElement('button');menu.dataset.tab='interactions';menu.textContent='⛏ Tương tác & linh thạch';$('mapMenu').querySelector('nav').append(menu);
 const shortcut=document.createElement('button');shortcut.id='editObjectInteraction';shortcut.textContent='⛏ Cấu hình tương tác vật thể';$('objectFields').prepend(shortcut);shortcut.onclick=()=>h.selectTab('interactions');
 const dock=document.createElement('div');dock.className='interaction-preview';dock.id='interactionPreview';dock.hidden=true;dock.innerHTML='<button id="testInteraction" class="primary" disabled>⚔ Tấn công · mô phỏng</button><progress id="interactionProgress" max="1" value="0"></progress><span id="interactionPreviewInfo"></span><small id="interactionPreviewWallet">Chỉ mô phỏng · không lưu tiền</small>';document.querySelector('.stage').append(dock);
 const on=(id,event,fn)=>$(id).addEventListener(event,h.safe(fn));let sim=null,boundProject=null,notice='',wallet=new Map(),listedObjects=null;
 const current=()=>h.selected(),mutate=fn=>{const id=current()?.id;if(!id)throw Error('Chọn một vật thể đã đặt trong map');h.update(p=>fn(p.objects.find(o=>o.id===id),p))};
 function refresh(){if(!h.state.project)return;const objects=h.state.project.objects,o=current();if(listedObjects!==objects){$('interactionObjectList').replaceChildren(new Option('— Chọn vật thể đã đặt —',''),...objects.map(o=>new Option((o.interaction?.enabled?'● ':'○ ')+o.id+' · '+(h.state.project.assets[o.asset].name||o.asset),o.id)));listedObjects=objects}$('interactionObjectList').value=o?.id||'';
  $('interactionFields').hidden=!o;$('jumpInteractiveObject').disabled=!o||h.state.busy;$('interactionSummary').textContent=objects.filter(o=>o.interaction?.enabled).length+' / '+objects.length+' vật thể cho phép tương tác · game nhận dạng bằng mapId + objectId.';if(!o)return;
  const i=o.interaction||defaultInteraction();$('interactiveObjectId').value=o.id;$('interactionEnabled').checked=!!o.interaction?.enabled;$('interactionSettings').hidden=!o.interaction?.enabled;
  for(const [id,key]of [['interactionType','type'],['interactionActionId','actionId'],['interactionLabel','label'],['interactionRange','range'],['interactionDuration','durationSeconds'],['interactionRespawn','respawnSeconds']])$(id).value=i[key];$('interactionDeplete').checked=i.deplete;$('interactionPointX').value=i.point.x;$('interactionPointY').value=i.point.y;$('interactionRewardFields').hidden=i.type==='custom';$('interactionResourceId').value=i.reward?.resourceId||'spirit_stone';$('interactionRewardMin').value=i.reward?.min||3;$('interactionRewardMax').value=i.reward?.max||8;
 }
 on('interactionObjectList','change',()=>{h.stop();h.selectObject($('interactionObjectList').value||null);refresh();h.focusObject(current())});on('interactiveObjectId','change',()=>h.renameObject($('interactiveObjectId').value.trim()));
 on('interactionEnabled','change',()=>mutate(o=>{o.interaction||=defaultInteraction();o.interaction.enabled=$('interactionEnabled').checked}));
 on('interactionType','change',()=>mutate(o=>{const i=o.interaction,d=defaultInteraction($('interactionType').value);o.interaction={...i,type:d.type,actionId:d.actionId,label:d.label,deplete:d.deplete,reward:d.reward}}));
 for(const [id,key]of [['interactionActionId','actionId'],['interactionLabel','label'],['interactionRange','range'],['interactionDuration','durationSeconds'],['interactionRespawn','respawnSeconds']])on(id,'change',()=>mutate(o=>o.interaction[key]=['actionId','label'].includes(key)?$(id).value.trim():$(id).valueAsNumber));
 on('interactionDeplete','change',()=>mutate(o=>o.interaction.deplete=$('interactionDeplete').checked));for(const [id,key]of [['interactionPointX','x'],['interactionPointY','y']])on(id,'change',()=>mutate(o=>o.interaction.point[key]=$(id).valueAsNumber));
 for(const [id,key]of [['interactionResourceId','resourceId'],['interactionRewardMin','min'],['interactionRewardMax','max']])on(id,'change',()=>mutate(o=>o.interaction.reward[key]=key==='resourceId'?$(id).value.trim():$(id).valueAsNumber));
 on('jumpInteractiveObject','click',()=>{h.stop();$('tool').value='select';h.selectTab('preview');h.focusObject(current())});
 on('downloadInteractionPrompt','click',async()=>{const r=await fetch(new URL('INTERACTIONS-CODEX.md',import.meta.url));if(!r.ok)throw Error('Không tải được prompt');h.download('INTERACTIONS-CODEX.md',await r.text(),'text/markdown')});
 on('testInteraction','click',()=>{if(!sim)return;if(sim.active){sim.cancel();notice='Đã hủy, chưa nhận tài nguyên.'}else{const t=sim.target(h.state.actor);if(t){h.prepareAction();sim.begin(t.objectId,h.state.actor);notice='Đang '+t.interaction.label.toLowerCase()+' · di chuyển sẽ hủy'}}});
 window.addEventListener('blur',()=>sim?.cancel());document.addEventListener('visibilitychange',()=>{if(document.hidden)sim?.cancel()});
 function tick(dt){
  if(!h.state.playing){sim=null;boundProject=null;wallet.clear();dock.hidden=true;return}
  if(!sim||boundProject!==h.state.project){sim=new InteractionSimulator(h.state.project);boundProject=h.state.project;notice='Chạy thử tương tác · không cộng tiền thật';wallet.clear()}dock.hidden=false;
  for(const event of sim.update(dt,h.state.actor)){if(event.type==='completed'){if(event.reward){const r=event.reward;wallet.set(r.resourceId,(wallet.get(r.resourceId)||0)+r.amount);notice='Thử nhận +'+r.amount+' '+(r.resourceId==='spirit_stone'?'Linh thạch':r.resourceId)}else notice='Đã thử hành động '+event.actionId;h.message(notice+' · chỉ mô phỏng')}if(event.type==='cancelled')notice='Đã hủy vì di chuyển / ra xa, chưa nhận tài nguyên.'}
  const active=sim.states.get(sim.active),target=sim.target(h.state.actor),button=$('testInteraction');button.disabled=!active&&!target;button.textContent=active?'■ Hủy thao tác':target?(target.interaction.type==='mine'?'⛏ ':target.interaction.type==='gather'?'✋ ':'◎ ')+target.interaction.label:'⚔ Tấn công · mô phỏng';$('interactionProgress').value=active?active.progress/active.definition.interaction.durationSeconds:0;$('interactionPreviewInfo').textContent=notice+(active?' · '+active.definition.objectId:target?' · gần '+target.objectId:' · đến gần vật thể đã bật tương tác');$('interactionPreviewWallet').textContent='Chỉ mô phỏng, không lưu tiền'+[...wallet].map(([id,n])=>' · '+(id==='spirit_stone'?'Linh thạch':id)+': '+n).join('');
 }
 return {refresh,tick,onTab:id=>{if(id==='interactions')h.focusObject(current()||h.state.project?.objects.find(o=>o.interaction?.enabled))},markers:()=>$('interactionMarkers').checked,objectState:id=>sim?.objectState(id),walkOptions:()=>sim?.walkOptions()||{}};
}
